/**
 * Guided practice labs for the Azure simulator. Each task is checked
 * automatically against the simulated state and activity log.
 */
import type { Sim } from './engine';
import { ME, type World } from './world';
import { AI_LABS } from './labs-ai';
import { DEV_LABS } from './labs-dev';

export interface LabTask {
  text: string;
  portal?: string;
  cli?: string;
  check: (s: Sim) => boolean;
}
export interface Lab {
  id: string;
  /** Exam the lab belongs to (default 'az-900'). */
  exam?: string;
  title: string;
  icon: string;
  level: 'Beginner' | 'Intermediate';
  minutes: number;
  start: 'portal' | 'shell';
  intro: string;
  learn: string[];
  topics: string[]; // related lesson slugs
  tasks: LabTask[];
  wrap: string;
}

const ev = (s: Sim, type: string, pred: (d: Record<string, any>) => boolean = () => true) => s.events.some((e) => e.type === type && pred(e.data));
const eq = (a = '', b = '') => a.toLowerCase() === b.toLowerCase();

